    def reverse(self, x: int) -> int:
        INT_MIN, INT_MAX = -2**31, 2**31 - 1
        sign = -1 if x < 0 else 1
        s = str(abs(x))[::-1]
        res = sign * int(s)
        if res < INT_MIN or res > INT_MAX:
            return 0
        return res

