class Solution {
    public int reverse(int x) {
        long ax = Math.abs((long) x);
        String s = new StringBuilder(Long.toString(ax)).reverse().toString();
        long res = Long.parseLong(s);
        if (x < 0) res = -res;
        if (res < Integer.MIN_VALUE || res > Integer.MAX_VALUE) return 0;
        return (int) res;
    }
}

